const input = $json.body ?? $json;
const description = String(input.description ?? '').trim();
if (description.length < 10) throw new Error('description must contain at least 10 characters');
const text = `${input.short_description ?? ''} ${description}`;
const security = /ransomware|data leak|compromis|active attack/i.test(text);
const outage = /all users|company[- ]wide|site[- ]wide|complete outage|service down/i.test(text);
const critical = Boolean(input.business_critical);
const users = Math.max(1, Number(input.affected_users) || 1);
let baseline_priority = 'P3';
if (security || (critical && outage)) baseline_priority = 'P1';
else if (outage || users >= 25 || critical) baseline_priority = 'P2';
else if (/request|how do i|information/i.test(text)) baseline_priority = 'P4';
return [{ json: { incident: input, baseline_priority, security_signal: security } }];

const baseline = $('Validate and set priority floor').first().json;
const raw = $json.choices?.[0]?.message?.content;
if (!raw) throw new Error('AI response did not contain message content');
let ai;
try { ai = JSON.parse(raw); } catch { throw new Error('AI response was not valid JSON'); }
const priorities = ['P1','P2','P3','P4'];
const rank = { P1:1, P2:2, P3:3, P4:4 };
const requested = priorities.includes(ai.priority) ? ai.priority : baseline.baseline_priority;
const priority = rank[requested] <= rank[baseline.baseline_priority] ? requested : baseline.baseline_priority;
const allowedCategories = ['Security','Identity & Access','Network','Endpoint','Application','Email & Collaboration','General IT'];
const category = allowedCategories.includes(ai.category) ? ai.category : 'General IT';
const confidence = Math.min(1, Math.max(0, Number(ai.confidence) || 0.5));
return [{ json: { schema_version:'1.0', incident_id:String(baseline.incident.incident_id ?? `DEMO-${Date.now()}`), short_description:String(baseline.incident.short_description ?? baseline.incident.description.slice(0,90)), category, service:String(ai.service ?? 'Service Desk'), priority, confidence, reasoning:String(ai.reasoning ?? 'AI reasoning unavailable').slice(0,500), initial_actions:Array.isArray(ai.initial_actions) ? ai.initial_actions.slice(0,5).map(String) : [], escalation_team:String(ai.escalation_team ?? 'Service Desk'), human_review_required:priority === 'P1' || priority === 'P2' || confidence < 0.7 || baseline.security_signal, ai_status:'enriched', baseline_priority:baseline.baseline_priority, data_notice:'Sanitized demonstration data only; human validation required.' } }];
